'@
# END GENERATED INSTALLER CORE

  $MinimumVerifierNodeMajor = 20

  function Write-StationFailure([string]$Message) {
    [Console]::Error.WriteLine("Station install failed: $Message")
  }

  function Test-NodeAdequate([string]$Executable) {
    try {
      # No quotes inside the argument: Windows PowerShell 5.1 passes embedded
      # double quotes to native programs unescaped.
      $version = & $Executable -p 'process.versions.node'
      if ($LASTEXITCODE -ne 0) { return $false }
      $number = 0
      if (-not [int]::TryParse(([string]$version).Split('.')[0], [ref]$number)) { return $false }
      return $number -ge $MinimumVerifierNodeMajor
    } catch {
      return $false
    }
  }

  # The profile as Node.js's os.homedir() reads it, so this script and the
  # core agree on the default root and on what is inside the profile.
  function Get-StationProfile {
    if ($env:USERPROFILE) { return $env:USERPROFILE }
    return [Environment]::GetFolderPath('UserProfile')
  }

  function Get-StationInstallRoot([string]$Channel) {
    if ($env:STATION_INSTALL_ROOT) { return $env:STATION_INSTALL_ROOT }
    $stationRoot = if ($env:STATION_ROOT -and $env:STATION_ROOT.Trim()) {
      $env:STATION_ROOT.Trim()
    } else {
      Join-Path (Get-StationProfile) '.station'
    }
    return Join-Path (Join-Path $stationRoot 'installs') $Channel
  }

  # True when $Path lies beneath the user profile with no reparse point on
  # the way down from it. Until install-root permissions are checked (#2675
  # slice W2), only such a root is trusted enough to run its Node.js before
  # anything is verified; the core refuses any other root anyway.
  function Test-InsideProfile([string]$Path) {
    $profileRoot = [IO.Path]::GetFullPath((Get-StationProfile)).TrimEnd('\')
    $full = [IO.Path]::GetFullPath($Path).TrimEnd('\')
    if (-not $full.StartsWith($profileRoot + '\', [StringComparison]::OrdinalIgnoreCase)) { return $false }
    $cursor = $profileRoot
    foreach ($part in $full.Substring($profileRoot.Length + 1).Split('\')) {
      $cursor = Join-Path $cursor $part
      if (-not (Test-Path -LiteralPath $cursor)) { break }
      if (([IO.File]::GetAttributes($cursor) -band [IO.FileAttributes]::ReparsePoint) -ne 0) { return $false }
    }
    return $true
  }

  function Save-PinnedNode([string]$Directory) {
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    $zip = Join-Path $Directory $PinnedNodeFile
    Write-Host "Downloading Node.js $PinnedNodeVersion to verify this install (no Node.js $MinimumVerifierNodeMajor or newer on PATH)..."
    $downloaded = $false
    for ($attempt = 1; $attempt -le 3 -and -not $downloaded; $attempt++) {
      try {
        Invoke-WebRequest -UseBasicParsing -Uri ($PinnedNodeOrigin + $PinnedNodeFile) -OutFile $zip
        $downloaded = $true
      } catch {
        if ($attempt -eq 3) { throw "could not download ${PinnedNodeFile}: $($_.Exception.Message)" }
        Start-Sleep -Seconds $attempt
      }
    }
    $actual = (Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actual -ne $PinnedNodeSha256) { throw "$PinnedNodeFile does not match its pinned sha256" }
    Add-Type -AssemblyName System.IO.Compression
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    $node = Join-Path $Directory 'node.exe'
    $archive = [IO.Compression.ZipFile]::OpenRead($zip)
    try {
      $entry = $archive.GetEntry($PinnedNodeEntry)
      if ($null -eq $entry) { throw "$PinnedNodeFile has no $PinnedNodeEntry" }
      [IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $node, $false)
    } finally {
      $archive.Dispose()
    }
    Remove-Item -LiteralPath $zip -Force
    if (-not (Test-NodeAdequate $node)) { throw "the pinned Node.js $PinnedNodeVersion does not run on this host" }
    return $node
  }

  function Resolve-VerifierNode([string]$Directory, [string]$Channel) {
    $hostNode = Get-Command node -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($null -ne $hostNode -and (Test-NodeAdequate $hostNode.Path)) {
      return $hostNode.Path
    }
    $installRoot = Get-StationInstallRoot $Channel
    $installed = Join-Path (Join-Path (Join-Path $installRoot 'current') 'runtime') 'node.exe'
    if ((Test-InsideProfile $installRoot) -and (Test-Path -LiteralPath $installed -PathType Leaf)) {
      $copyDirectory = Join-Path $Directory 'installed-node'
      [void](New-Item -ItemType Directory -Path $copyDirectory)
      $copy = Join-Path $copyDirectory 'node.exe'
      Copy-Item -LiteralPath $installed -Destination $copy
      if (Test-NodeAdequate $copy) {
        Write-Host 'Using the Node.js of the installed Station to verify this install.'
        return $copy
      }
    }
    if ($env:STATION_INSTALL_PUBLIC_MANIFEST_URL) {
      $pinnedDirectory = Join-Path $Directory 'node'
      [void](New-Item -ItemType Directory -Path $pinnedDirectory)
      return Save-PinnedNode $pinnedDirectory
    }
    throw "Node.js $MinimumVerifierNodeMajor or newer is required to verify a Station release; install it, or set STATION_INSTALL_PUBLIC_MANIFEST_URL so the pinned Node.js can be downloaded"
  }

  $channel = if ($env:STATION_CHANNEL) { $env:STATION_CHANNEL } else { 'stable' }
  # The core validates the channel too; this check only keeps an invalid
  # value out of the installed-runtime path below.
  if ($channel -ne 'preview' -and $InstallableRuntimeChannels -notcontains $channel) {
    Write-StationFailure "STATION_CHANNEL must be one of: $($InstallableRuntimeChannels -join ' ')"
    return 1
  }

  # A relative root would resolve against two different directories here:
  # .NET's GetFullPath uses the process directory, while Test-Path and
  # Copy-Item use PowerShell's current location. So every root must be
  # absolute (drive-qualified or UNC), and is refused before any Node.js is
  # looked for, let alone run. The core applies the same rule.
  foreach ($name in @('STATION_ROOT', 'STATION_INSTALL_ROOT', 'STATION_HOME')) {
    $value = [Environment]::GetEnvironmentVariable($name)
    if ($null -eq $value -or $value.Trim() -eq '') { continue }
    if ($value.Trim() -notmatch '^(?:[A-Za-z]:[\\/]|[\\/]{2}[^\\/])') {
      Write-StationFailure "$name must be an absolute path: $value"
      return 1
    }
  }

  # The user's temporary directory is private to the user by default.
  $temporary = Join-Path ([IO.Path]::GetTempPath()) ('station-install.' + [guid]::NewGuid().ToString('N'))
  [void](New-Item -ItemType Directory -Path $temporary)
  $savedTemporary = $env:STATION_INSTALLER_TEMP
  try {
    try {
      $node = Resolve-VerifierNode $temporary $channel
    } catch {
      Write-StationFailure $_.Exception.Message
      return 1
    }
    $core = Join-Path $temporary 'station-installer-core.cjs'
    [IO.File]::WriteAllBytes($core, [Convert]::FromBase64String(($StationInstallerCore -replace '\s', '')))
    $env:STATION_INSTALLER_TEMP = $temporary
    # Out-Host, so the core's output reaches the console instead of becoming
    # this block's return value.
    & $node $core @args | Out-Host
    return $LASTEXITCODE
  } finally {
    $env:STATION_INSTALLER_TEMP = $savedTemporary
    Remove-Item -LiteralPath $temporary -Recurse -Force -ErrorAction SilentlyContinue
  }
} @args

# `powershell -File install.ps1` reports the status as its exit code. Text run
# through Invoke-Expression (`irm | iex`) sees an empty $PSCommandPath and
# empty $args, even inside a caller's script run with arguments (the Windows
# smoke checks both PowerShells), so it takes no arguments and never exits the
# caller: a failure is reported and the caller continues.
if ($PSCommandPath) {
  exit $stationInstallStatus
} elseif ($stationInstallStatus -ne 0) {
  Write-Warning "The Station installer exited with status $stationInstallStatus."
}
